async function run(ctx) {
  const question = ctx.trigger.payload.question || "用一句话介绍你自己";
  ctx.tools.log("提问:", question);
  const r = await ctx.tools.exec(
    `claude -p ${JSON.stringify(question + "（用中文简洁回答）")}`,
    { timeoutMs: 150000 }
  );
  if (r.exitCode !== 0) { ctx.tools.fail("claude 调用失败: " + r.stderr.slice(0, 200)); }
  return { question: question, answer: r.stdout.trim() };
}
